  spacing: 8,
  runSpacing: 8,
  children: [
    for (final filter in _filters)
      LumoChip(
        label: filter,
        isSelected: _selected.contains(filter),
        onChanged: (on) => setState(
          () => on ? _selected.add(filter) : _selected.remove(filter),
        ),
        onRemove: () => setState(() => _filters.remove(filter)),
        removeLabel: 'حذف $filter',
      ),
  ],
)

